<?php
namespace App\Services;
use App\Models\{Expense,Group,User}; use App\Exceptions\{InvalidExpenseSplitException,UnauthorizedGroupAccessException}; use Illuminate\Support\Facades\DB;
class ExpenseService {
 public function create(array $d,Group $g,User $u):Expense { $ids=array_map('strval',$g->member_ids??[]); if(!in_array((string)$d['paid_by'],$ids,true)) throw new UnauthorizedGroupAccessException('The payer is not a member of this group.',422); foreach($d['participants'] as $p) if(!in_array((string)$p['user_id'],$ids,true)) throw new UnauthorizedGroupAccessException('A participant is not a member of this group.',422); $parts=$this->split($d['amount'],$d['split_type'],$d['participants']); return DB::connection('mongodb')->transaction(fn()=>Expense::create(['group_id'=>(string)$g->_id,'description'=>$d['description'],'amount'=>(float)$d['amount'],'paid_by'=>(string)$d['paid_by'],'split_type'=>$d['split_type'],'participants'=>$parts])); }
 public function update(Expense $e,array $d,Group $g,User $u):Expense { $parts=$this->split($d['amount'],$d['split_type'],$d['participants']);$e->fill(['description'=>$d['description'],'amount'=>(float)$d['amount'],'paid_by'=>(string)$d['paid_by'],'split_type'=>$d['split_type'],'participants'=>$parts]);$e->save();return $e; }
 private function split(float $amount,string $type,array $participants):array { if(count($participants)<1)throw new InvalidExpenseSplitException('At least one participant is required.',422); if($type==='equal'){ $share=round($amount/count($participants),2);$parts=[];$remaining=$amount;foreach($participants as $i=>$p){$v=$i===count($participants)-1?round($remaining,2):$share;$remaining-=$v;$parts[]=['user_id'=>(string)$p['user_id'],'amount'=>$v];}return $parts;} if($type==='exact'){ $sum=round(array_sum(array_map(fn($p)=>(float)($p['amount']??0),$participants)),2);if(abs($sum-$amount)>0.01)throw new InvalidExpenseSplitException('Exact participant amounts must equal the expense total.',422);return array_map(fn($p)=>['user_id'=>(string)$p['user_id'],'amount'=>(float)$p['amount']],$participants);} $sum=round(array_sum(array_map(fn($p)=>(float)($p['percentage']??0),$participants)),2);if(abs($sum-100)>0.01)throw new InvalidExpenseSplitException('Participant percentages must equal 100%.',422);return array_map(fn($p)=>['user_id'=>(string)$p['user_id'],'amount'=>round($amount*((float)$p['percentage']/100),2),'percentage'=>(float)$p['percentage']],$participants); }
}
